static void forceDelete(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File must not be null");
    }
    if (file.isDirectory()) {
        forceDeleteDirectory(file);
    } else {
        boolean deleted = file.delete();
        if (!deleted) {
            throw new IOException("Failed to delete file: " + file);
        }
    }
}

static void forceDeleteDirectory(File directory) throws IOException {
    if (directory == null) {
        throw new NullPointerException("Directory must not be null");
    }

    Deque<File> queue = new ArrayDeque<>();
    queue.push(directory);
    while (!queue.isEmpty()) {
        File head = queue.pop();
        if (head.isDirectory()) {
            for (String name : head.list()) {
                queue.push(new File(head, name));
            }
        }
        boolean deleted = head.delete();
        if (!deleted) {
            throw new IOException("Failed to delete file: " + head);
        }
    }
}

public static void forceDeleteOnExit(File file) throws IOException {

    // Check if the file is null
    if (file == null) {
        throw new NullPointerException("File is null");
    }

    // Delete the file or directory
    if (file.isDirectory()) {
        File[] files = file.listFiles();
        if (files != null) {
            for (File nestedFile : files) {
                forceDeleteOnExit(nestedFile);
            }
        }
    }
    file.deleteOnExit();
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file.isDirectory()) {
        deleteDirectory(file);
    } else {
        file.deleteOnExit();
    }
}

private static void deleteDirectory(File directory) throws IOException {
    if (!directory.exists()) {
        return;
    }

    File[] files = directory.listFiles();
    if (files != null) {
        for (File file : files) {
            if (file.isDirectory()) {
                deleteDirectory(file);
            } else {
                file.delete();
            }
        }
    }

    directory.delete();
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file.isDirectory()) {
        file.delete();
        File[] subFiles = file.listFiles();
        if (subFiles != null) {
            for (File subFile : subFiles) {
                forceDeleteOnExit(subFile);
            }
        }
    }
    Runtime.getRuntime().addShutdownHook(new Thread(() -> {
        file.delete();
    }));
}

public static void forceDeleteOnExit(File file) throws IOException {
  if (!file.exists()) {
    return;
  }

  if (file.isDirectory()) {
    file.listFiles().forEach(f -> forceDeleteOnExit(f));
  }

  file.deleteOnExit();
}

