public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
target = new Graph<>();
int numVertexA = 0;
int numVertexB = 0;
for(Map.Entry<String,V> entry : resultMap.entrySet()) {
V key = entry.getKey();
V value = entry.getValue();
int degree = target.degree(key);
if(degree % 2 == 0) {
numVertexA++;
} else {
numVertexB++;
}
}

for(V key : resultMap.keySet()) {
