public void generateGraph(Graph<V,E> target, Map<String, V> resultMap) {
target.clear();
Map<String, Integer> vertexMap = new HashMap<>();

for (String s : resultMap.keySet()) {
    V v = resultMap.get(s);
    Integer vertexId = vertexMap.get(s);

    if (vertexId == null) {
        vertexId = target.addVertex(v);
        vertexMap.put(s, vertexId);
    }
}

for (String s1 : resultMap.keySet()) {
    V vertex1 = resultMap.get(s1);
    Integer vertexId1 = vertexMap.get(s1);

    for (String s2 : resultMap.keySet()) {
        if (!s1.equals(s2)) {
            V vertex2 = resultMap.get(s2);
            Integer vertexId2 = vertexMap.get(s2);

            if (vertexId1 != null && vertexId2 != null) {
                E edge = target.addEdge(vertexId1, vertexId2);
                vertex1.getEdges().add(edge);
                vertex2.getEdges().add(edge);
            }
        }
    }
}

Map<String, V> reversedVertexMap = new HashMap<>();
for (V v : target.getVertices()) {
    reversedVertexMap.put(v.toString(), v);
}

for (V v : target.getVertices()) {
    for (E e : v.getEdges()) {
        V targetVertex = e.getTarget();
        V reversedTargetVertex = reversedVertexMap.get(targetVertex.toString());
        target.setEdge(v, reversedTargetVertex, e);
    }
}

return target;
}

public void generateGraph(Graph<V,E> target, Map<String, V> resultMap) {
target.clearEdges();
List<V> vertexList = new ArrayList<>();
List<E> edgeList = new ArrayList<>();
for (Map.Entry<String,V> entry : resultMap.entrySet()) {
Vertex source = entry.getValue();
if (!vertexList.contains(source)) {
vertexList.add(source);
}

for (Map.Entry<String, V> neighborEntry : resultMap.entrySet()) {
String neighbor = neighborEntry.getKey();
Vertex neighborVertex = neighborEntry.getValue();
if (!neighbor.equals(entry.getKey()) && neighborVertex.equals(source)) {
edgeList.add(new E(source, neighborVertex));
}
}
}

for (E edge : edgeList) {
target.addEdge(edge);
}
}

public void generateBipartiteGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Step 1: Create vertex sets for the left and right sides of the bipartite graph
    Set<V> leftVertices = new HashSet<>();
    Set<V> rightVertices = new HashSet<>();
    for (V vertex : target.getVertices()) {
        if (vertex.getDegree() % 2 == 0) {
            leftVertices.add(vertex);
        } else {
            rightVertices.add(vertex);
        }
    }

    // Step 2: Add edges between the vertex sets
    for (V leftVertex : leftVertices) {
        for (V rightVertex : rightVertices) {
            if (leftVertex != rightVertex) {
                E edge = new E(leftVertex, rightVertex);
                target.addEdge(edge);
            }
        }
    }
}

