public static int writeDelimitedTo(OutputStream out, Object message, Schema schema, LinkedBuffer buffer) throws IOException {
        int messageSize = schema.sizeof(message);
        out.write(messageSize);
        out.write(buffer.clear());
        return messageSize;
    }

public static int writeDelimitedTo(OutputStream out, Object message, Schema<?> schema, LinkedBuffer buffer) throws IOException {

    // Serialize the message
    byte[] serializedMessage = schema.serialize(message);

    // Write the length of the message
    out.writeInt(serializedMessage.length);

    // Write the message itself
    out.write(serializedMessage);

    return serializedMessage.length;
}

public static int writeDelimitedTo(OutputStream out, Object message, Schema schema, LinkedBuffer buffer) throws IOException {
    // Write the length of the message as a varint
    out.write(CodedOutputStream.encodeRawVarint32(message.size()));
    // Serialize the message
    CodedOutputStream codedOutput = CodedOutputStream.newInstance(out, buffer);
    schema.writeTo(codedOutput);
    // Return the size of the message
    return codedOutput.size();
}

public static int writeDelimitedTo(OutputStream out, Object message, Schema schema, LinkedBuffer buffer) throws IOException {
    int size = message.getSerializedSize();
    byte[] bytes = new byte[size + 4];
    bytes[0] = (byte)((size >>> 24) & 0xFF);
    bytes[1] = (byte)((size >>> 16) & 0xFF);
    bytes[2] = (byte)((size >>> 8) & 0xFF);
    bytes[3] = (byte)size & 0xFF;
    int pos = 4;
    byte[] bufferArray;
    if (buffer == null) {
        bufferArray = new byte[schema.getSerializedSize(message)];
    } else {
        bufferArray = buffer.toByteArray();
    }
    schema.writeTo(message, bufferArray, 0);
    System.arraycopy(bufferArray, 0, bytes, pos, bufferArray.length);
    pos += bufferArray.length;
    out.write(bytes, 0, pos);
    return size;
}

