private static Class[] resolveArguments(Type genericType, Class targetType) {
    if (genericType instanceof Class) {
      return null;
    }

    if (genericType instanceof ParameterizedType) {
      ParameterizedType parameterizedType = (ParameterizedType) genericType;
      Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
      Class[] resolvedArguments = new Class[actualTypeArguments.length];

      for (int i = 0; i < actualTypeArguments.length; i++) {
        Type actualTypeArgument = actualTypeArguments[i];
        resolvedArguments[i] = resolveClass(actualTypeArgument, targetType);
      }

      return resolvedArguments;
    }

    return null;
  }

private static Class resolveClass(Type type, Class targetType) {
    if (type instanceof Class) {
      return (Class) type;
    }

    if (type instanceof ParameterizedType) {
      ParameterizedType parameterizedType = (ParameterizedType) type;
      Type rawType = parameterizedType.getRawType();

      if (rawType instanceof Class) {
        return (Class) rawType;
      }

      if (rawType instanceof ParameterizedType) {
        return targetType;
      }
    }

    return null;
  }

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
      return null;
    }

    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
    Class<?>[] resolvedArguments = new Class<?>[actualTypeArguments.length];

    for (int i = 0; i < actualTypeArguments.length; i++) {
      Type actualTypeArgument = actualTypeArguments[i];
      Class<?> resolvedArgument = resolveType(actualTypeArgument, targetType);
      if (resolvedArgument != null) {
        resolvedArguments[i] = resolvedArgument;
      } else {
        return null;
      }
    }

    return resolvedArguments;
  }

private static Class<?> resolveType(Type type, Class<?> targetType) {
    if (type instanceof Class<?>) {
      return (Class<?>) type;
    } else if (type instanceof TypeVariable) {
      TypeVariable<?> typeVariable = (TypeVariable<?>) type;
      return resolveBound(typeVariable.getBounds(), targetType);
    } else if (type instanceof ParameterizedType) {
      return resolveType(((ParameterizedType) type).getRawType(), targetType);
    } else {
      return null;
    }
  }

private static Class<?> resolveBound(Type[] bounds, Class<?> targetType) {
    for (Type bound : bounds) {
      Class<?> resolvedBound = resolveType(bound, targetType);
      if (resolvedBound != null) {
        return resolvedBound;
      }
    }
    return null;
  }

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType instanceof ParameterizedType) {

        ParameterizedType parameterizedType = (ParameterizedType) genericType;

        Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();

        Class<?>[] resolvedArguments = new Class<?>[actualTypeArguments.length];

        for (int i = 0; i < actualTypeArguments.length; i++) {
            Type typeArgument = actualTypeArguments[i];

            if (typeArgument instanceof Class) {
                resolvedArguments[i] = (Class<?>) typeArgument;
            } else if (typeArgument instanceof TypeVariable) {
                TypeVariable<?> typeVariable = (TypeVariable<?>) typeArgument;

                resolvedArguments[i] = resolveTypeVariable(typeVariable, targetType);
            }
        }

        return resolvedArguments;
    }

    return null;
}

