public Mappings diffStructure(String tableName, Mappings mappings) {
    Map<String, Object> currentMappings = mappings.get(tableName);

    // Get all fields from current mapping
    Set<String> allFields = new HashSet<>();
    for (Map<String, Object> field : (List<Map<String, Object>>) currentMappings.get("properties")) {
        allFields.add((String) field.get("name"));
    }

    // Get all fields from the input mapping
    Set<String> inputFields = new HashSet<>();
    for (Map<String, Object> field : (List<Map<String, Object>>) mappings.get("properties")) {
        inputFields.add((String) field.get("name"));
    }

    // Get the fields that not exist in the input mapping
    Set<String> diffFields = new HashSet<>();
    diffFields.addAll(allFields);
    diffFields.removeAll(inputFields);

    // Create a new Mappings object with the fields that not exist in the input mapping
    Mappings newMappings = new Mappings();
    for (String field : diffFields) {
        Field fieldConfiguration = new Field((String) currentMappings.get("name"), field);
        newMappings.addField(fieldConfiguration);
    }

    return newMappings;
}

