public long readLong(int offset) {
    int low = readUnsignedShort(offset);
    int high = readUnsignedShort(offset + 2);
    int lowBytes = 0xffff & low;
    int highBytes = 0xffff & high;
    return (((long) highBytes) << 16) + lowBytes;
}

