public static long compressTimeBucket(long timeBucket, int dayStep) {
    long year = timeBucket / 100000000;
    long month = (timeBucket / 1000000 - year * 100) / 100;
    long day = timeBucket / 10000 - year * 10000 - month * 100;

    long revisedDay = day - (day - dayStep + 1) % dayStep;
    long revisedTimeBucket = year * 100000000 + month * 1000000 + revisedDay * 10000 + (timeBucket % 10000);

    return revisedTimeBucket;
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    return timeBucket - (timeBucket % dayStep) + 1;
}

static long compressTimeBucket(long timeBucket,int dayStep){
    // Calculate the number of days since the start of the time bucket
    int daysSinceBucket = (int) (timeBucket / 1000000);

    // Calculate the number of days to add to the current day
    int daysToAdd = daysSinceBucket % dayStep;

    // Calculate the number of days to subtract from the current day
    int daysToSubtract = dayStep - daysToAdd;

    // Calculate the new time bucket value
    long newTimeBucket = timeBucket - (daysToSubtract * 1000000);

    return newTimeBucket;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    return timeBucket - (timeBucket % dayStep);
}

public Long compressTimeBucket(long timeBucket, int dayStep) {
	Long revisedTimeBucket = null;

	Calendar cal = Calendar.getInstance();
	cal.setTimeInMillis(timeBucket);
	int currentDay = cal.get(Calendar.DAY_OF_MONTH);
	int currentMonth = cal.get(Calendar.MONTH);
	int currentYear = cal.get(Calendar.YEAR);

	if (dayStep == 1) {
		revisedTimeBucket = timeBucket;
	} else if (dayStep == 2) {
		cal.set(Calendar.DATE, currentDay + dayStep - 1);
		revisedTimeBucket = cal.getTimeInMillis();
	} else if (dayStep == 3) {
		cal.set(Calendar.MONTH, currentMonth + dayStep - 1);
		revisedTimeBucket = cal.getTimeInMillis();
	} else {
		cal.set(Calendar.YEAR, currentYear + dayStep - 1);
		revisedTimeBucket = cal.getTimeInMillis();
	}

	return revisedTimeBucket;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    for (int i = index; i < len; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            size++;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (c >= 0xD800 && c <= 0xDFFF) {
            size += 4;
        } else {
            size += 3;
        }
    }
    return size;
}

