  for (int i = 0; i < strLen; i++) {
    char ch = str.charAt(i);
    if (ch < 128) {
      lb.putByte((byte) ch);
    } else if (ch < 2048) {
      lb.putByte((byte) (0xc0 | (ch >> 6)));
      lb.putByte((byte) (0x80 | (ch & 0x3f)));
    } else if (ch < 0xD800) {
      lb.putByte((byte) (0xe0 | (ch >> 12)));
      lb.putByte((byte) (0x80 | ((ch >> 6) & 0x3f)));
      lb.putByte((byte) (0x80 | (ch & 0x3f)));
