public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
  // Validate input
  if (u == null) {
    throw new IllegalArgumentException("u cannot be null");
  }

  // Split the path into segments
  String[] segments = u.getPath().split("/");

  // Create a list to store the decoded path segments
  List<PathSegmentImpl> pathSegments = new ArrayList<>();

  // Iterate through the segments and decode them
  for (String segment : segments) {
    // Check if the segment is empty or null
    if (segment.isEmpty() || segment.equals("")) {
      continue;
    }

    // Decode the segment if necessary
    if (decode) {
      segment = URLDecoder.decode(segment, "UTF-8");
    }

    // Add the decoded segment to the list
    pathSegments.add(new PathSegmentImpl(segment, false));
  }

  // Return the list of decoded path segments
  return pathSegments;
}

