public long readRawVarint64() throws IOException {
	int shift = 0;
	long result = 0;
	while (shift < 64) {
		int b = this.getRawByte();
		result |= (long)(b & 0x7F) << shift;
		if ((b & 0x80) == 0) {
			break;
		}
		shift += 7;
	}
	return result;
}

