public int readRawVarint32() throws IOException {
    int result = 0;
    int offset = 0;
    // Read at most 6 bytes.
    for (; offset < 6; offset++) {
        long b = readRawByte();
        result |= (int) (b & 0x7F) << offset * 7;
        if ((b & 0x80) == 0) break;
    }
    if (offset == 6) {
        throw new IOException("Invalid varint: " + result);
    }
    if ((result & (1L << (64 - 7))) != 0) {
        // Sign extend.
        result |= (long) -1 << offset * 7;
    }
    return result;
}

public byte readRawByte() throws IOException {
