    Box2D leftBox = new Box2D(middlePoint, newDimensions);
    Box2D rightBox = new Box2D(middlePoint.add(new Vector2D(newDimensions.x, 0)), newDimensions);

    return new Pair<>(leftBox, rightBox);
}

