    int size = 0;

    while (node != null) {
        out.write(node.value);
        size++;

        node = node.next;
    }

    return size;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;
    while (node != null) {
        Object current = node.getValue();
        if (current instanceof Integer) {
            totalSize += out.writeInt((Integer) current);
        } else if (current instanceof Long) {
            totalSize += out.writeLong((Long) current);
        } else if (current instanceof String) {
            totalSize += out.writeUTF((String) current);
        } else if (current instanceof byte[]) {
            totalSize += out.write((byte[]) current);
        } else if (current instanceof CharSequence) {
            totalSize += out.writeChars((CharSequence) current);
        } else if (current instanceof Float) {
            totalSize += out.writeFloat((Float) current);
        } else if (current instanceof Double) {
            totalSize += out.writeDouble((Double) current);
        } else if (current instanceof Boolean) {
            totalSize += out.writeBoolean((Boolean) current);
        } else {
            throw new UnsupportedOperationException("Unsupported object type: " + current.getClass().getName());
        }
        node = node.getNext();
    }
    return totalSize;
}

