private void putAbstractTypes(final int start, final int end){
for (int i = start; i < end; i++){
final Object type = currentFrame.get(i);
if (type instanceof NullMarker){
pushCode(0x00);
} else if (type instanceof IntegerMarker){
pushCode(0x03);
} else if (type instanceof FloatMarker){
pushCode(0x04);
} else if (type instanceof LongMarker){
pushCode(0x05);
} else if (type instanceof DoubleMarker){
pushCode(0x06);
} else if (type instanceof ReferenceMarker){
final ReferenceMarker reference = (ReferenceMarker) type;
pushCode(0x07);
pushCode((reference.getReferenceIndex() >> 8) & 0xFF);
pushCode(reference.getReferenceIndex() & 0xFF);
} else {
throw new IllegalArgumentException("unknown type " + type);
}
}
}

