public static int nextPrime(int desiredCapacity) {
    int prime = desiredCapacity;
    while (true) {
        prime++;
        if (prime % 2 == 0 && prime >= 2) {
            continue;
        }
        int divisor = 3;
        while (divisor * divisor <= prime) {
            if (prime % divisor == 0) {
                break;
            }
            divisor += 2;
        }
        if (divisor * divisor > prime) {
            return prime;
        }
    }
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity >= 1000) {
        return (int)(desiredCapacity / (1 - desiredCapacity / 10000) + 1);
    } else {
        return (int)(desiredCapacity / (1 - desiredCapacity / 11) + 1);
    }
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 0) {
        throw new IllegalArgumentException("Desired capacity must be a positive integer");
    }

    if (desiredCapacity == 0) {
        return 1;
    }

    // Handle edge cases
    if (desiredCapacity == 1 || desiredCapacity == 2) {
        return desiredCapacity;
    }

    // Find the closest prime number to the desired capacity by iterating through the prime numbers starting from 3
    // and checking if any of them is greater than or equal to the desired capacity
    for (int prime = 3; prime <= 11 * desiredCapacity / 10; prime += 2) {
        if (prime >= desiredCapacity) {
            return prime;
        }
    }

    // If no prime number was found, return the maximum prime number less than the desired capacity
    return 11 * desiredCapacity / 10;
}

public static int nextPrime(int desiredCapacity) {
    # If the desired capacity is 0 or negative, set it to the default value of 1
    if(desiredCapacity <= 0) desiredCapacity = 1

    # Set the minimum possible value for a prime number
    minPrime = 1

    # Set the maximum possible value for a prime number
    maxPrime = 31

    # Set the range of possible values for a prime number
    while(maxPrime - minPrime > 1) {
        # Get the middle value of the range
        prime = (minPrime + maxPrime) / 2

        # Check if the prime number is greater than or equal to the desired capacity
        if(prime >= desiredCapacity) {
            # If yes, set the prime number as the output and break out of the loop
            return prime
        } else {
            # If no, set the minimum prime number as the output and break out of the loop
            minPrime = prime
        }
    }

    # Return the minimum prime number
    return minPrime
}

