            if (i == len - 1) {
                throw new Exception("Unterminated escape sequence at end of string");
            }
            c = sb.charAt(i + 1);
            switch (c) {
                case 'n':
                    sb.setCharAt(i++, '\n');
                    break;
                case 'b':
                    sb.setCharAt(i++, '\b');
                    break;
                case 't':
                    sb.setCharAt(i++, '\t');
                    break;
                case 'f':
                    sb.setCharAt(i++, '\f');
                    break;
                case 'r':
                    sb.setCharAt(i++, '\r');
                    break;
                case '\'':
                    sb.setCharAt(i++, '\'');
                    break;
                case '\"':
                    sb.setCharAt(i++, '\"');
                    break;
