public static int binaryLog(int n) {
    double log2 = Math.log(n) / Math.log(2);
    int log2Floor = (int) Math.floor(log2);
    if (log2 == log2Floor) {
        return log2Floor;
    } else {
        return log2Floor + 1;
    }
}

