protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    List<E> edges = new ArrayList<>(tour);
    List<V> vertices = new ArrayList<>();
    for (E edge : edges) {
        vertices.add(graph.getEdgeSource(edge));
        vertices.add(graph.getEdgeTarget(edge));
    }
    return new GraphPathImpl<>(graph, vertices);
}

private GraphPath<Vertex, Edge> edgeSetToTour(Set<Edge> tour, Graph<Vertex, Edge> graph) {
    // create a new graph path
    GraphPath<Vertex, Edge> path = new GraphPath<>(graph.vertices.size());

    // iterate over the edges in the tour
    for (Edge edge : tour) {
        // get the source and target vertices of the edge
        Vertex source = graph.mapEdgesToVertices.get(edge);
        Vertex target = graph.mapEdgesToVertices.get(edge);

        // add the edge to the graph path
        path.add(source, target);
    }

    // return the graph path
    return path;
}

