    if (this.getNumberOfRows() != dataset.getNumberOfRows()) {
        return false;
    }

    // Check if the bucket has the same column names
    if (!this.getColumnNames().equals(dataset.getColumnNames())) {
        return false;
    }

    // Check if the bucket has the same column types
    if (!this.getColumnTypes().equals(dataset.getColumnTypes())) {
        return false;
    }

    // Check if the bucket has the same column values
    if (!this.getColumnValues().equals(dataset.getColumnValues())) {
        return false;
    }

    // If all checks pass, return true
    return true;
}

