boolean unlink(ListNodeImpl<E> node){
if (node == null)
   return false;

// Check if the node is the head of the list
if (node.next == null)
   return false;

// Check if the node is the tail of the list
if (node.prev.next == node)
   node.prev.next = null;

// Check if the node is the only element in the list
if (node.prev == node)
   return true;

// Unlink the node from the list
node.prev.next = node.next;
node.next.prev = node.prev;

return true;
}

public boolean unlink(ListNode<E> node) {
if (node == null) return false;
if (node.getPrevious() == null) {
head = node.getNext();
} else {
node.getPrevious().setNext(node.getNext());
}
if (node.getNext() == null) {
tail = node.getPrevious();
} else {
node.getNext().setPrevious(node.getPrevious());
}
node.setNext(null);
node.setPrevious(null);
return true;
}

public boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }

    // remove the node from the list
    node.prev.next = node.next;
    node.next.prev = node.prev;
    node.prev = null;
    node.next = null;

    return true;
}

public void unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }

    if (node.prev == null) {
        // node is the head of the list
        head = node.next;
    } else {
        node.prev.next = node.next;
    }

    if (node.next == null) {
        // node is the tail of the list
        tail = node.prev;
    } else {
        node.next.prev = node.prev;
    }

    node.prev = null;
    node.next = null;

    size--;

    return true;
}

private boolean unlink(ListNodeImpl<E> node) {

    // If the node is the first node in the list, set the next node of the previous node to null
    if (node.next != null) {
        ListNodeImpl<E> nextNode = node.next;
        nextNode.prev = node.prev;
    }

    // Set the previous node of the next node to null (if any)
    if (node.prev != null) {
        ListNodeImpl<E> prevNode = node.prev;
        prevNode.next = node.next;
    }

    // Set the node's next and previous pointers to null
    node.next = null;
    node.prev = null;

    return true;
}

