private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    List<Integer> suffixSum = new ArrayList<>();
    long sumAll = 0;

    for (int i = bounds.size() - 1; i >= 0; i--) {
        int element = bounds.get(i);
        sumAll += element;
        suffixSum.add(element);
    }

    return new Pair<>(suffixSum, sumAll);
}

private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds) {
		List<Integer> suffixSum = new ArrayList<>();
		long sum = 0L;
		for (int i = 0; i < bounds.size(); i++) {
			sum += bounds.get(i);
			suffixSum.add((int) sum);
		}
		return new Pair<>(suffixSum, sum);
	}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    IntStream stream = bounds.stream().mapToInt(integer -> integer);
    long[] suffixSums = stream.toArray();
    for (int i = suffixSums.length - 2; i >= 0; i--) {
        suffixSums[i] += suffixSums[i + 1];
    }
    List<Integer> suffixSumList = Arrays.asList(suffixSums);
    long sum = suffixSums[0];
    return new Pair<>(suffixSumList, sum);
}

private List<Integer> computeSuffixSum(List<Integer> bounds){
    List<Integer> suffixSum = new LinkedList<>();
    long sum = 0;
    for(int i = bounds.size() - 1; i >= 0; i--){
        sum += bounds.get(i);
        suffixSum.add(0, sum);
    }
    return new Pair<>(suffixSum, sum);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    List<Integer> suffixSumList = new ArrayList<>();
    long sum = 0L;
    for (int i = 0; i < bounds.size(); i++) {
        int currentSum = 0;
        for (int j = i; j < bounds.size(); j++) {
            currentSum += bounds.get(j);
        }
        suffixSumList.add(currentSum);
        sum += currentSum;
    }
    return new Pair<>(suffixSumList, sum);
}

