private List<Pair<List<Pair<Integer,Integer>>,E>> computeMinimalSeparators(E e) {
    // Initialize the list of minimal separators
    List<Pair<List<Pair<Integer,Integer>>,E>> minimalSeparators = new ArrayList<>();
    // Iterate over all vertices in the neighborhood of the current edge
    for (V v : graph.neighborhood(e)) {
        // Compute the list of minimal separators for the current vertex
        List<Pair<List<Pair<Integer,Integer>>,E>> vertexSeparators = computeMinimalSeparators(v);
        // Add the list of minimal separators for the current vertex to the global separator list
        minimalSeparators.addAll(vertexSeparators);
    }
    // Return the list of minimal separators for the current edge
    return minimalSeparators;
}

private List<Pair<List<Pair<Integer,Integer>>, E>> computeGlobalSeparatorList() {
    List<Pair<List<Pair<Integer,Integer>>, E>> globalSeparatorList = new ArrayList<>();
    for (E e : graph.edgeSet()) {
        List<Pair<Integer,Integer>> separatorList = new ArrayList<>();
        List<Pair<Integer,Integer>> neighbors = graph.neighborListOf(e);
        for (Pair<Integer,Integer> neighbor : neighbors) {
            List<Pair<Integer,Integer>> separator = computeSeparator(e, neighbor.getFirst(), neighbor.getSecond());
            separatorList.addAll(separator);
        }
        globalSeparatorList.add(new Pair<>(separatorList, e));
    }
    return globalSeparatorList;
}

private List<Pair<Integer,Integer>> computeSeparator(E e, int src, int dst) {
    List<Pair<Integer,Integer>> separator = new ArrayList<>();
    separator.add(new Pair<>(src, dst));
    for (E neighbor : graph.edgeSet()) {
        if (graph.containsEdge(src, neighbor.getFirst()) && graph.containsEdge(neighbor.getSecond(), dst)) {
            separator.add(neighbor);
        }
    }
    return separator;
}

private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList() {
    // Initialize the list of minimal separators for each edge
    List<Pair<List<Pair<Integer,Integer>>,E>> minimalSeparators = new ArrayList<>();

    // Iterate over all edges in the graph
    for (E edge : graph.edges()) {
        // Compute the minimal separators for the current edge
        List<Pair<Integer,Integer>> separators = computeMinimalSeparators(edge);
        minimalSeparators.add(new Pair<>(separators, edge));
    }

    // Return the list of minimal separators for every edge in the graph
    return minimalSeparators;
}

private List<Pair<Integer,Integer>> computeMinimalSeparators(E edge) {
    // Initialize the list of minimal separators
    List<Pair<Integer,Integer>> separators = new ArrayList<>();

    // Get the nodes connected to the edge
    int node1 = graph.getNode1(edge);
    int node2 = graph.getNode2(edge);

    // Iterate over all nodes in the graph
    for (int node : graph.nodes()) {
        // Check if the current node is not connected to the edge
        if (node == node1 || node == node2) {
            continue;
        }

        // Compute the minimal separator of the current node with respect to the edge
        Pair<Integer,Integer> minimalSeparator = computeMinimalSeparator(node, edge);
        separators.add(minimalSeparator);
    }

    // Return the list of minimal separators for the edge
    return separators;
}

private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(){
    // compute the separator list for every edge in the graph
    List<Pair<List<Pair<Integer,Integer>>,E>> separatorList = new ArrayList<>();
    for(E e : graph.getEdges()){
        // compute the minimal separators in the neighborhood of e
        List<Pair<Integer,Integer>> separators = computeMinimalSeparators(e);
        separatorList.add(new Pair<>(separators, e));
    }
    return separatorList;
}

private List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList() {
    List<Pair<List<Pair<Integer, Integer>>, E>> globalSeparatorList = new ArrayList<>();
    for (E e : graph.edgeSet()) {
        List<Pair<Integer, Integer>> separators = new ArrayList<>();
        for (Pair<Integer, Integer> v : graph.getNeighbors(e)) {
            separators.add(new Pair<>(v.getKey(), v.getValue()));
        }
        globalSeparatorList.add(new Pair<>(separators, e));
    }
    return globalSeparatorList;
}

