public void selectRow(int row, JTable table, JScrollPane pane) {

  /*
   * Selects a the specified row in the specified JTable and scrolls
   * the specified JScrollpane to the newly selected row.
   *
   * @param row the row to select
   * @param table the JTable that should contain the selected row
   * @param pane the JScrollPane that should be scrolled to the selected row
   */

  // Select the specified row in the JTable
  table.setRowSelectionInterval(row, row);

  // Get the index of the newly selected row
  int newRowIndex = table.getSelectedRow();

  // Get the height of the row to be scrolled
  int rowHeight = table.getRowHeight(row);

  // Get the current vertical scroll value
  int currentScrollValue = pane.getVerticalScrollBar().getValue();

  // Calculate the new vertical scroll value
  int newScrollValue = currentScrollValue + (newRowIndex - pane.getVerticalScrollBar().getValue()) * rowHeight;

  // Scroll to the new position
  pane.getVerticalScrollBar().setValue(newScrollValue);

  // Repaint the JTable and JScrollPane to show the newly selected row
  table.repaint();
  pane.repaint();
}

public static void selectRow(int row, JTable table, JScrollPane pane) {

  // Select the specified row in the JTable
  table.changeSelection(row, true, true);

  // Find the location of the newly selected row
  int location = table.getSelectedRow();

  // Make sure the location is within the visible range of the JScrollPane
  if (location < pane.getVerticalScrollBar().getValue() || location >= (pane.getVerticalScrollBar().getValue() + pane.getVerticalScrollBar().getVisibleAmount() - table.getRowHeight())) {

    // Scroll the JScrollPane to the newly selected row
    pane.getVerticalScrollBar().setValue(location);
  }

  // Repaint the JTable after the scroll position change
  table.repaint(table.getVisibleRect());

  // Delay repaint long enough to allow the table to properly paint the newly selected row
  SwingUtilities.invokeLater(() -> table.repaint(table.getVisibleRect()));
}

