public ByteVector putInt(final int intValue) {
    // get the byte array representation of the int
    byte[] intBytes = ByteBuffer.allocate(4)
            .order(ByteOrder.BIG_ENDIAN)
            .putInt(intValue)
            .array();

    // iterate over the byte array and add each byte to this vector
    for (byte b : intBytes) {
        add(b);
    }

    return this;
}

public ByteBuffer putInt(int intValue) {
    if (remaining() < 4) {
        resize(4);
    }
    int bytes = intValue;
    put((byte)(bytes >> 24));
    put((byte)(bytes >> 16));
    put((byte)(bytes >> 8));
    put((byte)bytes);
    return this;
}

public ByteVector putInt(final int intValue){
    // Enlarge the byte vector if necessary
    if (byteBuffer.length < INT_BYTES){
        byte[] newByteArray = new byte[byteBuffer.length * 2];
        System.arraycopy(byteBuffer, 0, newByteArray, 0, byteBuffer.length);
        byteBuffer = newByteArray;
    }

    // Shift the bytes in the vector to make room for the new int
    int byteIndex = INT_BYTES - 1;
    while (byteIndex >= 0 && byteBuffer[byteIndex] != 0){
        byteBuffer[byteIndex + INT_BYTES] = byteBuffer[byteIndex];
        byteIndex--;
    }

    // Write the new int to the byte vector
    byteBuffer[byteIndex] = (byte) (intValue & 0xFF);
    byteBuffer[byteIndex + 1] = (byte) ((intValue >> 8) & 0xFF);
    byteBuffer[byteIndex + 2] = (byte) ((intValue >> 16) & 0xFF);
    byteBuffer[byteIndex + 3] = (byte) ((intValue >> 24) & 0xFF);

    return this;
}

public ByteVector putInt(final int intValue) {
  // Add the int value to the byte vector
  for (int i = 0; i < 4; i++) {
    this.add((byte)(intValue >>> (i * 8)));
  }
  return this;
}

public ByteVector putInt(int intValue) {
    // determine the number of bytes needed to represent the int value
    int bytesNeeded = (intValue.numberOfBytes() + 1);
    // check if the underlying array needs to be resized
    if (array.length < bytesNeeded) {
        // resize the underlying array
        byte[] newArray = new byte[bytesNeeded];
        // copy the old bytes to the new array
        System.arraycopy(array, 0, newArray, 0, array.length);
        // update the reference to the underlying array
        array = newArray;
    }
    // convert the int value to a byte array
    byte[] intBytes = intValue.toByteArray();
    // put the byte array into the byte vector
    putBytes(intBytes);
    // return this byte vector
    return this;
}

