}

public static boolean isClique(Graph<?, ?> graph, Set<?> vertices) {
    // Check if the subgraph is connected
    if (!isConnected(graph, vertices)) {
        return false;
    }

    // Check if the subgraph is complete
    Set<Pair<V, V>> edges = new HashSet<>();
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (v1.equals(v2)) {
                continue;
            }
            edges.add(new Pair<>(v1, v2));
        }
    }
    return graph.edgeSet().containsAll(edges);
}

public static boolean isConnected(Graph<?, ?> graph, Set<?> vertices) {
    // Find the connected components of the subgraph
    Set<Set<V>> components = new HashSet<>();
    for (V v : vertices) {
        Set<V> component = new HashSet<>();
        component.add(v);
        components.add(component);
    }

    // Merge the connected components
    for (E edge : graph.edgeSet()) {
        V v1 = graph.getEdgeSource(edge);
        V v2 = graph.getEdgeTarget(edge);
        for (Set<V> component : components) {
            if (component.contains(v1) && component.contains(v2)) {
                component.add(v2);
                break;
            }
        }
    }

    // Check if the connected components are all one
    return components.size() == 1;
}

