private void pop(final String descriptor) {
    final int dimension = Type.getType(descriptor).getDimensions();
    for (int i = 0; i < dimension; i++) {
        final AbstractType value = this.outputFrame.pop();
        if (value == null) {
            throw new IllegalStateException("Not enough values on the stack");
        }
        if (!value.isReference()) {
            throw new IllegalStateException("Cannot pop value of type " + value.getClass().getSimpleName());
        }
        if (!value.getType().equals(Type.getType(descriptor))) {
            throw new IllegalStateException("Expected value of type " + Type.getType(descriptor) + " but got " + value.getType());
        }
    }
}

private void pop(final String descriptor) {
    if (descriptor.startsWith("(")) {
        // Method descriptor, pop argument types
        String[] argTypes = descriptor.substring(1, descriptor.length() - 1).split(";");
        for (String argType : argTypes) {
            if (!argType.isEmpty()) {
                stack.pop();
            }
        }
    } else {
        // Type descriptor, pop single type
        stack.pop();
    }
}

private void pop(final String descriptor) {
    while (!getStackTrace().isEmpty() && getStackTrace().peek() instanceof AbstractType) {
        if (descriptor == null || ((AbstractType) getStackTrace().peek()).getDescriptor().equals(descriptor)) {
            getStackTrace().pop();
        } else {
            break;
        }
    }
}

void pop(String descriptor) {
    if (descriptor.contains("(")) {
        // Method descriptor
        while (getStackDepth() > 0 && !descriptor.startsWith("(" + getStackItemType(0))) {
            popStack();
        }
    } else {
        // Type descriptor
        while (getStackDepth() > 0 && !descriptor.equals(getStackItemType(0))) {
            popStack();
        }
    }
}

public void pop(String descriptor) {
    // Calculate the number of abstract types to pop from the output frame stack
    int numAbstractTypes = 0;
    if (descriptor.charAt(0) == '(') {
        numAbstractTypes = calculateNumArguments(descriptor);
    } else {
        numAbstractTypes = 1;
    }

    // Pop the appropriate number of abstract types from the output frame stack
    for (int i = 0; i < numAbstractTypes; i++) {
        outputFrameStack.pop();
    }
}

private int calculateNumArguments(String descriptor) {
    int numArguments = 0;
    int index = 1;
    while (descriptor.charAt(index) != ')') {
        if (descriptor.charAt(index) == 'L') {
            while (descriptor.charAt(index) != ';') {
                index++;
            }
        }
        numArguments++;
        index++;
    }
    return numArguments;
}

