public static String applyRelativePath(String path, String relativePath) {
    // split the path into individual components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // iterate through the relative path components
    for (String component : relativePathComponents) {
        // if the component is "..", remove the last path component
        if (component.equals("..")) {
            pathComponents = Arrays.copyOfRange(pathComponents, 0, pathComponents.length - 1);
        }
        // if the component is not "..", add it to the end of the path
        else {
            pathComponents = Arrays.copyOf(pathComponents, pathComponents.length + 1);
            pathComponents[pathComponents.length - 1] = component;
        }
    }

    // join the path components back into a single string
    StringBuilder sb = new StringBuilder();
    for (String component : pathComponents) {
        sb.append("/");
        sb.append(component);
    }
    return sb.toString();
}

