    int lastSeparatorIndex = path.lastIndexOf("/");
    return path.substring(0, lastSeparatorIndex + 1) + relativePath;
}

public static String applyRelativePath(String path, String relativePath) {
    // Check if the path is null
    if (path == null) {
        throw new IllegalArgumentException("Path cannot be null");
    }

    // Check if the relative path is null
    if (relativePath == null) {
        throw new IllegalArgumentException("Relative path cannot be null");
    }

    // Split the path into directories
    String[] directories = path.split("/");

    // Split the relative path into directories
    String[] relativeDirectories = relativePath.split("/");

    // Create a new arraylist to store the resulting directories
    ArrayList<String> resultingDirectories = new ArrayList<>();

    // Iterate over the directories in the path
    for (String directory : directories) {
        // If the directory is "..", remove the last directory from the resulting directories
        if (directory.equals("..")) {
            if (resultingDirectories.size() > 0) {
                resultingDirectories.remove(resultingDirectories.size() - 1);
            }
        } else {
            // Otherwise, add the directory to the resulting directories
            resultingDirectories.add(directory);
        }
    }

    // Iterate over the relative directories
    for (String relativeDirectory : relativeDirectories) {
        // If the relative directory is ".", do nothing
        if (relativeDirectory.equals(".")) {
            // Do nothing
        } else {
            // Otherwise, add the relative directory to the resulting directories
            resultingDirectories.add(relativeDirectory);
        }
    }

    // Join the resulting directories with "/"
    return String.join("/", resultingDirectories);
}

