int readTag() throws IOException {
    int tag = 0;
    while (true) {
        int b = stream.read();
        if (b == -1 || b == 0) {
            break;
        }
        tag = (tag << 7) | (b & 0x7F);
        if ((b & 0x80) == 0) {
            break;
        }
    }
    return tag;
}

int readTag() throws IOException {
    int tag = input.read();
    while (tag == 0) {
        if (input.read() == -1) {
            return 0;
        }
        tag = input.read();
    }
    return tag;
}

