public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

    try(FileInputStream fis = new FileInputStream(file)) {
        BufferedReader reader = new BufferedReader(new InputStreamReader(fis));
        String line;
        while((line = reader.readLine()) != null) {
            String[] fields = line.split("\t");
            if(fields.length != 4 || !fields[0].equals("TIME")) {
                continue;
            }
            long timeStamp = Long.parseLong(fields[1]);
            TimeUnit unit = TimeUnit.valueOf(fields[2]);
            int id = Integer.parseInt(fields[3]);
            ProfileAnalyzeTimeRange timeRange = timeRanges.stream().filter(range -> range.getId() == id).findAny().orElse(null);
            if(timeRange == null) {
                continue;
            }
            if(timeRange.getStartTime().getTime() <= timeStamp && timeRange.getEndTime().getTime() >= timeStamp) {
                ThreadSnapshot threadSnapshot = new ThreadSnapshot();
                threadSnapshot.setTimeStamp(timeStamp);
                threadSnapshot.setTimeUnit(unit);
                threadSnapshot.setThreadId(id);
                threadSnapshots.add(threadSnapshot);
            }
        }
    }
    return threadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            String[] parts = line.split("\\t");
            Long time = Long.parseLong(parts[0]);
            String threadName = parts[1];
            String state = parts[2];
            String stackTrace = parts[3];
            ThreadSnapshot snapshot = new ThreadSnapshot(time, threadName, state, stackTrace);
            snapshots.add(snapshot);
        }
    }
    Collections.sort(snapshots, new Comparator<ThreadSnapshot>() {
        @Override
        public int compare(ThreadSnapshot o1, ThreadSnapshot o2) {
            return (int) (o1.getTimestamp() - o2.getTimestamp());
        }
    });
    if (timeRanges != null) {
        for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
            Long startTime = timeRange.getStartTime();
            Long endTime = timeRange.getEndTime();
            List<ThreadSnapshot> filteredSnapshots = new ArrayList<>();
            for (ThreadSnapshot snapshot : snapshots) {
                if (snapshot.getTimestamp() >= startTime && snapshot.getTimestamp() <= endTime) {
                    filteredSnapshots.add(snapshot);
                }
            }
            timeRange.setThreadSnapshots(filteredSnapshots);
        }
    }
    return snapshots;
}

