    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (InputStream inputStream = new FileInputStream(file)) {
        BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream));
        String line;
        while ((line = reader.readLine()) != null) {
            String[] tokens = line.split(",");
            long timestamp = Long.parseLong(tokens[0]);
            long duration = Long.parseLong(tokens[1]);
            String threadName = tokens[2];
            ProfileAnalyzeTimeRange timeRange = getTimeRange(timestamp, duration);
            if (timeRange != null) {
                ThreadSnapshot threadSnapshot = new ThreadSnapshot(threadName, timestamp, duration);
                threadSnapshots.add(threadSnapshot);
            }
        }
    }
    return threadSnapshots;
}

private static ProfileAnalyzeTimeRange getTimeRange(long timestamp, long duration) {
    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
        if (timeRange.contains(timestamp, duration)) {
            return timeRange;
        }
    }
    return null;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            // check if the line contains the time range
            for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                if (line.matches("[0-9]+ [0-9]+ [0-9]+ [0-9]+ [0-9]+ 00:00:00")) {
                    // get the time range from the line
                    String[] times = line.split(" ");
                    String timeStartStr = times[0] + " " + times[1] + " " + times[2] + " " + times[4] + " " + times[5];
                    String timeEndStr = times[3] + " " + times[4] + " " + times[5] + " " + times[7] + " " + times[8];

                    // check if the time range is within the requested time range
                    if (timeRange.getTimeStart().before(timeStartStr) && timeRange.getTimeEnd().after(timeEndStr)) {
                        // parse the snapshot from the line
                        ThreadSnapshot snapshot = new ThreadSnapshot(times[0] + " " + times[1] + " " + times[2] + " " + times[4] + " " + times[5],
                                times[3] + " " + times[4] + " " + times[5] + " " + times[7] + " " + times[8],
                                times[6] + " " + times[7] + " " + times[8]);
                        threadSnapshots.add(snapshot);
                    }
                }
            }
        }
    }

    return threadSnapshots;
}

